sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float keyChannel;
uniform float amount;
uniform float method;
uniform float tolerance;
uniform float compensate;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 o = s;
    float limitv = 0.0;
    float excess = 0.0;
    if (keyChannel < 0.5) {
        limitv = method < 0.5 ? (s.r + s.b) * 0.5 : max(s.r, s.b);
        excess = max(s.g - limitv - tolerance, 0.0);
        o.g = s.g - excess * amount;
    } else if (keyChannel < 1.5) {
        limitv = method < 0.5 ? (s.r + s.g) * 0.5 : max(s.r, s.g);
        excess = max(s.b - limitv - tolerance, 0.0);
        o.b = s.b - excess * amount;
    } else {
        limitv = method < 0.5 ? (s.g + s.b) * 0.5 : max(s.g, s.b);
        excess = max(s.r - limitv - tolerance, 0.0);
        o.r = s.r - excess * amount;
    }
    o += (luma(s) - luma(o)) * compensate;
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
